// ESP32 WebSocket Server for FRC Dashboard
#include <WiFi.h>
#include <WebSocketsServer.h>
#include <ArduinoJson.h>

const char* ssid = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";

WebSocketsServer webSocket = WebSocketsServer(8080);

void setup() {
  Serial.begin(115200);

  // Connect to WiFi
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }

  Serial.println("WiFi connected!");
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  // Start WebSocket server
  webSocket.begin();
  webSocket.onEvent(webSocketEvent);
}

void loop() {
  webSocket.loop();

  // Send telemetry data every second
  static unsigned long lastSend = 0;
  if (millis() - lastSend > 1000) {
    sendTelemetryData();
    lastSend = millis();
  }
}

void sendTelemetryData() {
  // Create JSON object with telemetry data
  DynamicJsonDocument doc(1024);

  doc["speed"] = random(0, 500) / 100.0;  // 0.0 to 5.0 m/s
  doc["temperature"] = random(200, 800) / 10.0;  // 20.0 to 80.0 °C
  doc["battery"] = random(100, 140) / 10.0;  // 10.0 to 14.0 V
  doc["distance"] = random(0, 1000) / 10.0;  // 0.0 to 100.0 m
  doc["angle"] = random(0, 3600) / 10.0;  // 0.0 to 360.0 degrees

  String jsonString;
  serializeJson(doc, jsonString);

  // Broadcast to all connected clients
  webSocket.broadcastTXT(jsonString);
}

void webSocketEvent(uint8_t num, WStype_t type, uint8_t * payload, size_t length) {
  switch(type) {
    case WStype_DISCONNECTED:
      Serial.printf("[%u] Disconnected!\n", num);
      break;
    case WStype_CONNECTED:
      Serial.printf("[%u] Connected from %s\n", num, payload);
      break;
    case WStype_TEXT:
      Serial.printf("[%u] Received: %s\n", num, payload);
      // Handle incoming commands here
      break;
  }
}
